from __future__ import annotations

import json

from ask.cae_gap_review import DEFAULT_CAE_REVIEWERS, parse_cae_reviewer_specs, run_cae_gap_review


def test_default_cae_reviewer_contract_roles_are_stable():
    assert parse_cae_reviewer_specs(DEFAULT_CAE_REVIEWERS) == [
        {"persona": "Brandon", "role": "cae_policy_evidence"},
        {"persona": "Margaret", "role": "cae_technical_enforcement"},
        {"persona": "Jennifer", "role": "cae_control_mapping"},
    ]


def test_cae_reviewer_contract_accepts_dash_role_aliases():
    assert parse_cae_reviewer_specs("Analyst:cae-policy-evidence") == [
        {"persona": "Analyst", "role": "cae_policy_evidence"}
    ]


def test_cae_gap_review_contract_is_advisory_and_routes_missing_evidence():
    calls: list[tuple[str, int]] = []

    def model_turn(**kwargs):
        calls.append((kwargs["persona"], kwargs["turn_number"]))
        if kwargs["persona"] == "CAE Gap Judge":
            return (
                json.dumps(
                    {
                        "review_id": "cae-case-1",
                        "decision": "NEEDS_CLARIFICATION",
                        "decision_summary": "Retrieved evidence needs one cited policy source.",
                        "cited_basis": [],
                        "missing_evidence": [
                            {
                                "missing_evidence_type": "policy_source",
                                "description": "Retrieve the policy source with a source_id.",
                                "needed_from": "policy_evidence",
                            }
                        ],
                        "route_to": "policy_evidence",
                        "stop_reason": "required_input_missing",
                        "final_status": "NEEDS_CLARIFICATION",
                    }
                ),
                "test-model",
                None,
            )
        return (
            json.dumps(
                {
                    "review_id": "cae-case-1",
                    "evidence_limits": ["memory_only_context"],
                    "rejection_check": {"rejected_items": [], "reason": ""},
                    "final_status": "NEEDS_VERIFICATION",
                }
            ),
            "test-model",
            None,
        )

    result = run_cae_gap_review(
        question="Review QRA evidence for AC-2 MFA.",
        scope="tenant",
        evidence_case={"case_id": "case-1", "memory_context": "not evidence"},
        max_rounds=1,
        model="test-model",
        reasoning_effort="low",
        timeout=1,
        idle_timeout=1,
        heartbeat_interval=1,
        backend="test",
        dogpile_mode="off",
        model_turn=model_turn,
    )

    assert {persona for persona, turn in calls if turn < 100} == {"Brandon", "Margaret", "Jennifer"}
    contract = result["gap_review_contract"]
    assert result["advisory_only"] is True
    assert contract["advisory_only"] is True
    assert contract["final_status"] == "NEEDS_CLARIFICATION"
    assert contract["route_to_persona"] == "Brandon"
    assert contract["missing_evidence"][0]["missing_evidence_type"] == "policy_source"
    assert "memory_or_dogpile_context_is_not_evidence" in contract["source_artifact_requirements"]
    assert contract["qra_correction_recommendation"]["requires_new_evidence_case"] is True
